def build_agent(sandbox):
    # Base beam (horizontal) at starting position
    base_beam = sandbox.add_beam(x=4.5, y=1.5, width=3.0, height=0.4, density=15.5)

    # First vertical beam (connected to base)
    first_vertical_beam = sandbox.add_beam(x=4.5, y=3.2, width=0.4, height=3.0, density=15.5)
    joint_base = sandbox.add_joint(base_beam, first_vertical_beam, anchor_point=(4.5, 1.7), type='pivot')

    # Second vertical beam (connected to first vertical beam)
    second_vertical_beam = sandbox.add_beam(x=4.5, y=4.7, width=0.4, height=0.6, density=15.5)
    joint_first = sandbox.add_joint(first_vertical_beam, second_vertical_beam, anchor_point=(4.5, 4.7), type='pivot')

    # Pads for adhesion
    pad1 = sandbox.add_pad(x=4.5, y=5.0, radius=0.25, density=0.8)  # Top of second vertical beam
    pad2 = sandbox.add_pad(x=4.5, y=4.7, radius=0.25, density=0.8)  # Top of first vertical beam

    # Joints connecting beams to pads
    joint_pad1 = sandbox.add_joint(second_vertical_beam, pad1, anchor_point=(4.5, 5.0), type='pivot')
    joint_pad2 = sandbox.add_joint(first_vertical_beam, pad2, anchor_point=(4.5, 4.7), type='pivot')

    # Control setup: alternate between pads and joints
    control = {
        'cycle': 10,
        'p_torso': [pad2],  # Pad2 is on the first vertical beam
        'p_arm': [pad1],    # Pad1 is on the second vertical beam
        'joint': joint_first,  # Joint for the second vertical beam
        'overlap': 10,
        'speed': 10.0,
        'torque': 100.0
    }

    return {
        'main': base_beam,
        'pads': [pad1, pad2],
        'joints': [joint_base, joint_first, joint_pad1, joint_pad2],
        'control': control
    }

def agent_action(sandbox, agent_body, step_count):
    _apply_climb_action(sandbox, agent_body, step_count)
